// Meta manda hub.verify_token: debe ser igual a WHATSAPP_VERIFY_TOKEN.
const q = $input.first().json.query ?? {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WHATSAPP_VERIFY_TOKEN;
return [{ json: { ok, challenge: ok ? String(q['hub.challenge'] ?? '') : 'token incorrecto' } }];

// 1) Firma de Meta: HMAC-SHA256 del cuerpo exacto con el App Secret.
//    Sin firma válida no se procesa nada.
const crypto = require('crypto');
const entrada = $input.first();
const firma = String(entrada.json.headers?.['x-hub-signature-256'] ?? '');
const crudo = await this.helpers.getBinaryDataBuffer(0, 'data');
const esperada = 'sha256=' + crypto.createHmac('sha256', $env.META_APP_SECRET).update(crudo).digest('hex');
const valida = firma.length === esperada.length && crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperada));
if (!valida) throw new Error('Firma de Meta no válida: mensaje descartado.');

// 2) Un ítem por mensaje (se ignoran los avisos de entregado/leído).
const cuerpo = JSON.parse(crudo.toString('utf8'));
const salida = [];
for (const e of cuerpo.entry ?? []) {
  for (const c of e.changes ?? []) {
    const v = c.value ?? {};
    for (const m of v.messages ?? []) {
      const contacto = (v.contacts ?? []).find((x) => x.wa_id === m.from);
      const base = { wa_id: m.id, celular: m.from, nombre: contacto?.profile?.name ?? '' };
      let tipo = 'otro', texto = '', boton_id = '', media_id = '', mime = '', archivo = '';
      if (m.type === 'text') { tipo = 'texto'; texto = m.text?.body ?? ''; }
      else if (m.type === 'audio') { tipo = 'audio'; media_id = m.audio.id; mime = m.audio.mime_type; archivo = 'audio.ogg'; }
      else if (m.type === 'image') { tipo = 'imagen'; media_id = m.image.id; mime = m.image.mime_type; texto = m.image.caption ?? ''; archivo = 'foto.jpg'; }
      else if (m.type === 'document') { tipo = 'documento'; media_id = m.document.id; mime = m.document.mime_type; texto = m.document.caption ?? ''; archivo = m.document.filename ?? 'documento.pdf'; }
      else if (m.type === 'video') { tipo = 'video'; media_id = m.video.id; mime = m.video.mime_type; texto = m.video.caption ?? ''; archivo = 'video.mp4'; }
      else if (m.type === 'interactive') { tipo = 'boton'; boton_id = m.interactive?.button_reply?.id ?? m.interactive?.list_reply?.id ?? ''; texto = m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title ?? ''; }
      else if (m.type === 'button') { tipo = 'boton'; boton_id = m.button?.payload ?? ''; texto = m.button?.text ?? ''; }
      salida.push({ json: { ...base, tipo, texto, boton_id, media_id, mime, archivo } });
    }
  }
}
return salida;

