// La app dice qué responder; aquí se arma el formato de Meta.
// Hasta 3 botones: botones. De 4 a 10: lista. Mensaje repetido: no se responde.
const salida = [];
for (const it of $input.all()) {
  const r = it.json;
  if (r.duplicado || !r.respuesta?.texto) continue;
  const botones = r.respuesta.botones ?? [];
  let mensaje;
  if (botones.length >= 1 && botones.length <= 3) {
    mensaje = { messaging_product: 'whatsapp', to: r.para, type: 'interactive', interactive: { type: 'button', body: { text: r.respuesta.texto.slice(0, 1024) }, action: { buttons: botones.map((b) => ({ type: 'reply', reply: { id: b.id, title: b.titulo.slice(0, 20) } })) } } };
  } else if (botones.length > 3) {
    mensaje = { messaging_product: 'whatsapp', to: r.para, type: 'interactive', interactive: { type: 'list', body: { text: r.respuesta.texto.slice(0, 1024) }, action: { button: 'Elegir', sections: [{ title: 'Opciones', rows: botones.slice(0, 10).map((b) => ({ id: b.id, title: b.titulo.slice(0, 24) })) }] } } };
  } else {
    mensaje = { messaging_product: 'whatsapp', to: r.para, type: 'text', text: { body: r.respuesta.texto.slice(0, 4096) } };
  }
  salida.push({ json: { mensaje } });
}
return salida;
